<template>
  <div class="page extension-page">
    <header class="page-heading">
      <div><span class="eyebrow">EXTENSION CONTROL PLANE</span><h1>{{ overview?.release.name || '扩展详情' }}</h1><p>查看技术扩展的发布、Capability、Worker 健康状态与真实执行链路。</p></div>
      <div class="heading-actions"><button v-if="publishableRelease" class="primary-button" :disabled="publishing" @click="publishRelease">{{ publishing ? '提交中…' : `发布 v${publishableRelease.version} 并等待 Worker 确认` }}</button><button class="secondary-button" :disabled="loading" @click="load">{{ loading ? '刷新中…' : '刷新' }}</button></div>
    </header>
    <section v-if="missingRelease" class="panel missing-release">
      <span class="eyebrow">EXTENSION NOT DISCOVERED</span><h2>此扩展尚未进入发布目录</h2>
      <p>先安装并在部署配置中启用 <code>{{ extensionId }}</code>，再执行目录发现。该操作只登记不可变 Manifest 和组件，不会启动 Agent、调用模型或执行 Capability。</p>
      <pre>uv pip install -e extensions/{{ extensionId }}
uv run joyhousebot discover-extensions --config config.json</pre>
      <div><router-link class="secondary-button" to="/extensions">返回扩展目录</router-link><button class="primary-button" @click="load">重新检查</button></div>
    </section>
    <div v-else-if="error" class="notice error-notice">{{ error }}</div>
    <template v-else-if="overview">
      <section class="release-strip panel"><div><span class="eyebrow">{{ overview.release.status.toUpperCase() }} RELEASE</span><strong>{{ overview.release.name }}</strong><small>{{ overview.release.extension_id }} · v{{ overview.release.version }} · {{ overview.release.status }}</small></div><div><span>组件</span><strong>{{ overview.components.length }}</strong></div><div><span>健康 Worker</span><strong>{{ overview.worker_summary.healthy_loaded }}/{{ overview.worker_summary.total }}</strong></div><div><span>24h 成功率</span><strong>{{ percent(overview.metrics.success_rate) }}</strong></div><div><span>P95</span><strong>{{ latency(overview.metrics.p95_duration_ms) }}</strong></div></section>
      <div v-if="pendingReleases.length" class="notice"><strong>待处理发布：</strong><span v-for="item in pendingReleases" :key="item.version">v{{ item.version }} · {{ item.status }} · {{ item.build_digest }}</span><small v-if="pendingReleases.some((item) => item.status === 'staged')">staged 版本已进入 rollout；请到平台治理查看 Worker 加载确认、批准、失败原因或安全回滚。</small><small v-else>discovered 仅表示目录已登记；可以先配置非敏感参数，真正生效仍需发布并由 Worker 加载确认。</small></div>
      <nav class="extension-tabs"><button v-for="item in tabs" :key="item.id" :class="{ active: tab === item.id }" @click="tab = item.id">{{ item.label }} <small>{{ item.count }}</small></button></nav>
      <section v-if="tab === 'overview'" class="extension-grid">
        <article class="panel"><span class="eyebrow">RELEASE</span><h2>{{ overview.release.description }}</h2><dl><dt>Distribution</dt><dd>{{ overview.release.distribution_name || '—' }}</dd><dt>Build</dt><dd>{{ overview.release.build_digest || '未声明' }}</dd></dl></article>
        <article class="panel"><span class="eyebrow">DEPENDENCIES</span><div class="dependency-list"><div v-for="item in dependencies" :key="String(item.id)"><i /> <strong>{{ item.name }}</strong><small>{{ item.kind }} · {{ item.required ? 'required' : 'optional' }}</small></div></div></article>
        <article class="panel wide"><span class="eyebrow">COMPONENT METRICS</span><div class="metric-table"><div v-for="item in overview.metrics.by_component" :key="item.capability_id"><code>{{ item.capability_id }}</code><span>{{ item.total }} calls</span><span>{{ item.failed }} failed</span><span>P95 {{ latency(item.p95_duration_ms) }}</span></div><p v-if="!overview.metrics.by_component.length" class="muted">暂无扩展调用记录。</p></div></article>
      </section>
      <section v-else-if="tab === 'playground'" class="playground-grid">
        <article class="panel playground-editor">
          <span class="eyebrow">CAPABILITY PLAYGROUND</span><h2>单能力测试</h2>
          <p>选择扩展提供的只读 Capability 或 Connector 进行独立验证。测试进入统一 Run、调用记录与 Artifact 链路。</p>
          <label class="config-field"><span>组件</span><select v-model="playgroundComponentId"><option v-for="item in overview.components" :key="item.component_id" :value="item.component_id">{{ item.component_type.toUpperCase() }} · {{ item.name }} · {{ item.reference_id }} v{{ item.reference_version }}</option></select></label>
          <template v-if="playgroundComponent">
            <p class="component-summary"><strong>{{ playgroundComponent.name }}</strong><code>{{ playgroundComponent.reference_id }} · v{{ playgroundComponent.reference_version }}</code></p>
            <p class="settings-note">{{ playgroundComponent.description || '无额外说明' }}</p>
            <template v-if="configurable(playgroundComponent)">
              <label class="config-field"><span>输入 JSON</span><textarea v-model="playgroundInput" rows="18" spellcheck="false" /></label>
              <details class="playground-schema"><summary>查看输入 Schema</summary><pre>{{ pretty(playgroundComponent.metadata.input_schema || {}) }}</pre></details>
              <p v-if="playgroundAllowed(playgroundComponent)" class="settings-note">直接执行不会经过协调 Agent 或模型规划；仅允许只读、已启用的 Capability / Connector。每次测试都会保留 Run、调用记录和 Artifact。</p>
              <p v-else class="settings-note protected-playground-note">此能力会产生外部副作用或费用，控制台禁止绕过 Agent 授权、权限与审批直接执行。请在 Agent 配置中显式授权后端到端试跑。</p>
              <div class="settings-actions"><button class="secondary-button" :disabled="playgroundRunning" @click="resetPlayground">恢复示例</button><button v-if="playgroundAllowed(playgroundComponent)" class="primary-button" :disabled="playgroundRunning" @click="runPlayground">{{ playgroundRunning ? '提交中…' : '直接执行 Capability' }}</button></div>
            </template>
          </template>
        </article>
        <article class="panel playground-result">
          <span class="eyebrow">{{ playgroundResultLabel }}</span><h2>{{ playgroundResultTitle }}</h2>
          <template v-if="playgroundComponent && configurable(playgroundComponent)">
            <p v-if="!playgroundRun" class="muted">提交后将在此显示 Run 状态和输出 Artifact。完整时序、输入和调用记录仍可在运行中心查看。</p>
            <template v-else>
            <dl><dt>Run</dt><dd><code>{{ playgroundRun.run_id }}</code></dd><dt>状态</dt><dd>{{ playgroundRun.status }}</dd></dl>
            <div class="result-actions"><button class="secondary-button" :disabled="playgroundRefreshing" @click="refreshPlayground">{{ playgroundRefreshing ? '刷新中…' : '刷新结果' }}</button><button class="primary-button" @click="openRun(playgroundRun!.run_id)">查看完整 Run →</button></div>
            <pre v-if="playgroundArtifact">{{ pretty(playgroundArtifact.content) }}</pre>
            <p v-else class="muted">Worker 完成后点击“刷新结果”读取该 Capability 输出 Artifact。</p>
            </template>
          </template>
          <p v-else class="muted">从左侧下拉选择一个组件开始测试。</p>
        </article>
      </section>
      <section v-else-if="tab === 'components'" class="components-workspace" :class="{ 'has-settings': selectedComponent && settings }">
        <div class="component-grid">
          <article v-for="item in overview.components" :key="item.component_id" class="panel component-card" :class="{ selected: selectedComponent?.component_id === item.component_id }">
            <div class="component-state"><span class="kind">{{ item.component_type }}</span><span v-if="configurable(item)" :class="['state-chip', componentReady(item) ? 'ready' : 'blocked']">{{ componentReady(item) ? 'Runtime 就绪' : 'Runtime 阻塞' }}</span><span v-if="item.metadata.requires_explicit_grant" class="state-chip protected">显式授权</span></div>
            <h2>{{ item.name }}</h2><code>{{ item.reference_id }} · v{{ item.reference_version }}</code><p>{{ item.description || '无额外说明' }}</p><small v-if="item.metadata.adapter">{{ item.metadata.adapter }}</small>
            <ul v-if="componentBlockers(item).length" class="component-blockers"><li v-for="blocker in componentBlockers(item)" :key="blocker">{{ blocker }}</li></ul>
            <div class="component-actions"><button v-if="playgroundAllowed(item)" class="primary-button" @click="openComponentPlayground(item)">打开 Playground</button><span v-else class="protected-note">外部写能力需由已授权 Agent 发起</span><button v-if="configurable(item)" class="secondary-button" @click="openSettings(item)">配置与启停</button></div>
          </article>
        </div>
        <aside v-if="selectedComponent && settings" class="panel settings-panel">
          <div class="settings-heading"><div><span class="eyebrow">RUNTIME SETTINGS</span><h2>{{ selectedComponent.name }}</h2><small>{{ selectedComponent.reference_id }} · 所有 Worker 将在下一次调用读取此配置</small></div><button class="secondary-button" @click="closeSettings">关闭</button></div>
          <div class="effective-state"><strong>Runtime 调度状态</strong><span :class="componentReady(selectedComponent) ? 'ready' : 'blocked'">{{ componentReady(selectedComponent) ? '已启用且 Worker 已加载' : '存在 Runtime 阻塞' }}</span><small v-for="blocker in componentBlockers(selectedComponent)" :key="blocker">{{ blocker }}</small></div>
          <div v-if="integrationChecks.length" class="credential-state"><strong>Worker 凭据状态</strong><span v-for="check in integrationChecks" :key="check.name" :class="check.status"><i />{{ check.name }} · {{ check.summary }}</span></div>
          <label class="switch-row"><input v-model="settings.enabled" type="checkbox" /><span><strong>启用组件</strong><small>关闭后 Agent 不再获得此能力，新的调用会被拒绝。</small></span></label>
          <SchemaConfigurationForm v-model="configurationDraft" :schema="settings.configuration_schema" />
          <details><summary>高级 JSON 编辑</summary><label class="config-field"><span>运行时配置 JSON</span><textarea v-model="settingsText" rows="10" spellcheck="false" /></label></details>
          <details><summary>配置 Schema</summary><pre>{{ pretty(settings.configuration_schema) }}</pre></details>
          <p class="settings-note">只可配置非敏感运行参数。API Key、Token、密码必须留在 Worker 环境；Console 只显示是否就绪，不读取密钥内容。</p>
          <div class="settings-actions"><button class="secondary-button" :disabled="settingsSaving" @click="resetSettings">恢复</button><button class="primary-button" :disabled="settingsSaving" @click="saveSettings">{{ settingsSaving ? '保存中…' : overview.worker_summary.healthy_loaded ? '保存并热加载' : '保存配置' }}</button></div>
        </aside>
      </section>
      <section v-else-if="tab === 'topology'" class="panel topology"><span class="eyebrow">EXECUTION RELATIONSHIPS</span><div v-if="topology" class="topology-list"><article v-for="node in topology.nodes" :key="node.id"><strong>{{ node.label }}</strong><small>{{ node.kind }}</small><p>{{ links(node.id).join(' · ') || '无下游关联' }}</p></article></div><p v-else class="muted">正在读取关联图…</p></section>
      <section v-else-if="tab === 'health'" class="health-grid"><article v-for="item in health?.checks" :key="item.name" class="panel"><span :class="['status-dot', item.status]" /><span class="eyebrow">{{ item.name }}</span><h2>{{ item.status }}</h2><p>{{ item.summary }}</p></article></section>
      <section v-else class="panel invocation-list"><span class="eyebrow">RECENT INVOCATIONS</span><article v-for="item in invocations" :key="item.invocation_id"><div><code>{{ item.capability_id }}</code><small>{{ item.invocation_id }} · {{ formatDate(item.created_at) }}</small></div><span :class="['status-badge', item.status]">{{ item.status }}</span><button class="secondary-button" @click="openRun(item.run_id)">查看 Run</button></article><p v-if="!invocations.length" class="muted">暂无调用记录。</p></section>
    </template>
  </div>
</template>

<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import SchemaConfigurationForm from '../components/SchemaConfigurationForm.vue'
import { createExtensionPlaygroundRun, getExtension, getExtensionHealth, getExtensionInvocations, getExtensionTopology, publishExtensionRelease, type ExtensionComponent, type ExtensionHealth, type ExtensionInvocation, type ExtensionOverview, type ExtensionTopology } from '../api/extensions'
import { getCapabilityRuntimeSettings, saveCapabilityRuntimeSettings, type CapabilityRuntimeSettings } from '../api/admin'
import { getRuntimeArtifacts, getRuntimeRun, type RuntimeArtifact, type RuntimeRun } from '../api/runtime'

const route = useRoute(); const router = useRouter(); const extensionId = computed(() => String(route.params.extensionId || '')); const loading = ref(false); const error = ref(''); const tab = ref('overview')
const overview = ref<ExtensionOverview | null>(null); const topology = ref<ExtensionTopology | null>(null); const health = ref<ExtensionHealth | null>(null); const invocations = ref<ExtensionInvocation[]>([])
const publishing = ref(false)
const missingRelease = computed(() => error.value === 'extension release not found')
const selectedComponent = ref<ExtensionComponent | null>(null); const settings = ref<CapabilityRuntimeSettings | null>(null); const configurationDraft = ref<Record<string, unknown>>({}); const settingsText = ref('{}'); const savedSettingsText = ref('{}'); const settingsSaving = ref(false)
const playgroundComponentId = ref(''); const playgroundInput = ref('{}')
const playgroundRun = ref<RuntimeRun | null>(null); const playgroundArtifact = ref<RuntimeArtifact | null>(null); const playgroundRunning = ref(false); const playgroundRefreshing = ref(false)
const pendingReleases = computed(() => (overview.value?.releases || []).filter((item) => item.status !== 'active' && item.status !== 'retired'))
const publishableRelease = computed(() => pendingReleases.value.find((item) => item.status === 'discovered') || null)
const playgroundComponent = computed(() => overview.value?.components.find((item) => item.component_id === playgroundComponentId.value) || null)
const playgroundResultLabel = computed(() => 'DURABLE CAPABILITY RESULT')
const playgroundResultTitle = computed(() => '执行结果')
const tabs = computed(() => [{ id: 'overview', label: '概览', count: '' }, { id: 'playground', label: '组件试验', count: overview.value?.components.length || 0 }, { id: 'components', label: '组件', count: overview.value?.components.length || 0 }, { id: 'topology', label: '关联图', count: topology.value?.edges.length || 0 }, { id: 'health', label: '健康', count: health.value?.checks.length || 0 }, { id: 'invocations', label: '调用', count: invocations.value.length }])
const dependencies = computed(() => overview.value?.release.manifest.dependencies || [])
const integrationChecks = computed(() => (health.value?.checks || []).filter((item) => !['release_catalog', 'worker_release'].includes(item.name)))
function percent(value: number) { return `${Math.round(value * 100)}%` }; function latency(value: number | null) { return value == null ? '—' : `${Math.round(value)} ms` }; function formatDate(value: string) { return new Date(value).toLocaleString('zh-CN') }
function pretty(value: unknown) { return JSON.stringify(value || {}, null, 2) }; function configurable(item: ExtensionComponent) { return item.component_type === 'capability' || item.component_type === 'connector' }
function componentReady(item: ExtensionComponent) { return item.metadata.execution_ready !== false }
function componentBlockers(item: ExtensionComponent) { return Array.isArray(item.metadata.execution_blockers) ? item.metadata.execution_blockers.map(String) : [] }
function playgroundAllowed(item: ExtensionComponent) { return configurable(item) && String(item.metadata.side_effect || 'none') === 'none' }
function links(id: string) { return (topology.value?.edges || []).filter((item) => item.source === id).map((item) => topology.value?.nodes.find((node) => node.id === item.target)?.label || item.target) }
async function load() { if (!extensionId.value) return; loading.value = true; error.value = ''; overview.value = null; try { const [item, graph, checks, recent] = await Promise.all([getExtension(extensionId.value), getExtensionTopology(extensionId.value), getExtensionHealth(extensionId.value), getExtensionInvocations(extensionId.value)]); overview.value = item; topology.value = graph; health.value = checks; invocations.value = recent.items; if (item.components.length) selectPlaygroundComponent(item.components[0]) } catch (cause) { error.value = cause instanceof Error ? cause.message : '读取扩展状态失败' } finally { loading.value = false } }
async function publishRelease() { if (!publishableRelease.value) return; publishing.value = true; error.value = ''; try { await publishExtensionRelease(extensionId.value, publishableRelease.value.version); await load() } catch (cause) { error.value = cause instanceof Error ? cause.message : '扩展发布失败' } finally { publishing.value = false } }
async function openSettings(item: ExtensionComponent) { selectedComponent.value = item; settings.value = null; error.value = ''; try { const value = await getCapabilityRuntimeSettings(item.reference_id, item.reference_version); settings.value = value; configurationDraft.value = { ...value.configuration }; settingsText.value = pretty(value.configuration); savedSettingsText.value = settingsText.value } catch (cause) { error.value = cause instanceof Error ? cause.message : '读取组件配置失败' } }
function closeSettings() { selectedComponent.value = null; settings.value = null; configurationDraft.value = {}; settingsText.value = '{}' }
function resetSettings() { settingsText.value = savedSettingsText.value; configurationDraft.value = JSON.parse(savedSettingsText.value) as Record<string, unknown> }
async function saveSettings() { if (!selectedComponent.value || !settings.value) return; let configuration: Record<string, unknown>; try { const parsed = JSON.parse(settingsText.value); if (!parsed || Array.isArray(parsed) || typeof parsed !== 'object') throw new Error('配置必须是 JSON 对象'); configuration = parsed as Record<string, unknown> } catch (cause) { error.value = cause instanceof Error ? cause.message : '配置 JSON 无效'; return } settingsSaving.value = true; error.value = ''; try { const value = await saveCapabilityRuntimeSettings(selectedComponent.value.reference_id, { enabled: settings.value.enabled, configuration }, selectedComponent.value.reference_version); settings.value = { ...settings.value, ...value, configuration_schema: settings.value.configuration_schema }; configurationDraft.value = { ...value.configuration }; settingsText.value = pretty(value.configuration); savedSettingsText.value = settingsText.value; selectedComponent.value.metadata.runtime_enabled = value.enabled; const blockers = componentBlockers(selectedComponent.value).filter((item) => item !== '能力已被操作员停用'); if (!value.enabled) blockers.unshift('能力已被操作员停用'); selectedComponent.value.metadata.execution_blockers = blockers; selectedComponent.value.metadata.execution_ready = value.enabled && blockers.length === 0 } catch (cause) { error.value = cause instanceof Error ? cause.message : '保存组件配置失败' } finally { settingsSaving.value = false } }
function openRun(runId: string) { void router.push(`/runs/${encodeURIComponent(runId)}`) }
function playgroundSample(item: ExtensionComponent | null) { if (!item) return {}; const exampleInput = item.metadata.example_input; const examplePrompt = item.metadata.example_prompt; return { input: exampleInput && typeof exampleInput === 'object' ? pretty(exampleInput) : '{}', prompt: typeof examplePrompt === 'string' ? examplePrompt : undefined } }
function resetPlayground() { const sample = playgroundSample(playgroundComponent.value); playgroundInput.value = sample.input || '{}'; playgroundArtifact.value = null; playgroundRun.value = null }
function selectPlaygroundComponent(item: ExtensionComponent) { playgroundComponentId.value = item.component_id; resetPlayground() }
function openComponentPlayground(item: ExtensionComponent) { tab.value = 'playground'; selectPlaygroundComponent(item) }
async function runPlayground() { const item = playgroundComponent.value; if (!item || !extensionId.value) return; let input: Record<string, unknown>; try { const value = JSON.parse(playgroundInput.value); if (!value || Array.isArray(value) || typeof value !== 'object') throw new Error('输入必须是 JSON 对象'); input = value as Record<string, unknown> } catch (cause) { error.value = cause instanceof Error ? cause.message : 'JSON 无效'; return } playgroundRunning.value = true; error.value = ''; playgroundArtifact.value = null; try { playgroundRun.value = await createExtensionPlaygroundRun(extensionId.value, { capability_id: item.reference_id, input }); await refreshPlayground() } catch (cause) { error.value = cause instanceof Error ? cause.message : '创建 Capability Playground Run 失败' } finally { playgroundRunning.value = false } }
async function refreshPlayground() { if (!playgroundRun.value) return; playgroundRefreshing.value = true; error.value = ''; try { const [run, artifacts] = await Promise.all([getRuntimeRun(playgroundRun.value.run_id), getRuntimeArtifacts(playgroundRun.value.run_id)]); playgroundRun.value = run; playgroundArtifact.value = artifacts.find((item) => item.name === 'direct-capability-output' || item.name.endsWith('-output')) || null } catch (cause) { error.value = cause instanceof Error ? cause.message : '读取 Playground 结果失败' } finally { playgroundRefreshing.value = false } }
watch(configurationDraft, (value) => { settingsText.value = pretty(value) }, { deep: true }); watch(playgroundComponentId, () => resetPlayground()); watch(extensionId, () => { tab.value = 'overview'; topology.value = null; health.value = null; invocations.value = []; void load() }); onMounted(load)
</script>

